tool.command:
ln -s $input_tpr_path ./input_tpr_path.$input_tpr_path.ext; #if $input_cpt_path: ln -s $input_cpt_path ./input_cpt_path.$input_cpt_path.ext; #end if #if $input_plumed_path: ln -s $input_plumed_path ./input_plumed_path.$input_plumed_path.ext; #end if #if $input_plumed_folder: mkdir -p input_folder; #for $dataset in $input_plumed_folder: cp '$dataset' input_folder/'$dataset.element_identifier'; #end for #end if #if $config_json: ln -s $config_json ./config_json.$config_json.ext; #end if
mdrun_plumed
#if $config_json: --config ./config_json.$config_json.ext #end if
--input_tpr_path ./input_tpr_path.$input_tpr_path.ext #if $input_cpt_path: --input_cpt_path ./input_cpt_path.$input_cpt_path.ext #end if #if $input_plumed_path: --input_plumed_path ./input_plumed_path.$input_plumed_path.ext #end if #if $input_plumed_folder: --input_plumed_folder ./input_folder #end if --output_gro_path $outname_output_gro_path --output_edr_path $outname_output_edr_path --output_log_path $outname_output_log_path #if $outname_output_trr_path: --output_trr_path $outname_output_trr_path #end if #if $outname_output_xtc_path: --output_xtc_path $outname_output_xtc_path #end if #if $outname_output_cpt_path: --output_cpt_path $outname_output_cpt_path #end if #if $outname_output_dhdl_path: --output_dhdl_path $outname_output_dhdl_path #end if --output_plumed_folder ./output_folder ;
mv $outname_output_gro_path $output_gro_path; mv $outname_output_edr_path $output_edr_path; mv $outname_output_log_path $output_log_path; if test -f $outname_output_trr_path; then mv $outname_output_trr_path $output_trr_path; fi; if test -f $outname_output_xtc_path; then mv $outname_output_xtc_path $output_xtc_path; fi; if test -f $outname_output_cpt_path; then mv $outname_output_cpt_path $output_cpt_path; fi; if test -f $outname_output_dhdl_path; then mv $outname_output_dhdl_path $output_dhdl_path; fi;
